import { assert, assertEquals } from "@std/assert";
import { slugifyRole } from "./bank.ts";

// The pool migration is generated by build.py, which runs validate.py first.
// This reads the newest one back without Python, so a hand edit, a broken
// generator or a bad merge shows up in the Edge Function suite too.
const migrations = new URL("../../../migrations/", import.meta.url);

async function newestPoolMigration(): Promise<string | null> {
  const names: string[] = [];
  for await (const entry of Deno.readDir(migrations)) {
    if (/^\d{4}_interview_pool_\w*\.sql$/.test(entry.name)) {
      names.push(entry.name);
    }
  }
  names.sort();
  return names.at(-1) ?? null;
}

const file = await newestPoolMigration();
const sql = file ? await Deno.readTextFile(new URL(file, migrations)) : "";

/** Every `$tag$…$tag$` JSON block, by tag. */
function blocks(): Record<string, unknown[]> {
  const out: Record<string, unknown[]> = {};
  for (const m of sql.matchAll(/\$(\w+)\$([\s\S]*?)\$\1\$/g)) {
    out[m[1]] = JSON.parse(m[2]);
  }
  return out;
}

interface Role {
  slug: string;
  title: string;
  cluster: string;
  field: string;
  summary: string;
  field_default: boolean;
  sort_order: number;
}
interface PoolQuestion {
  id: string;
  role: string | null;
  kind: string;
  difficulty: string;
  category: string;
  question: string;
  key_points: string[];
  source_url: string | null;
  sort_order: number;
}
interface FixedSet {
  role: string;
  session_type: string;
  difficulty: string;
  questions: { question: unknown }[];
}

const LEGACY = [
  "frontend-developer",
  "backend-developer",
  "data-analyst",
  "digital-marketer",
  "hr-executive",
  "business-analyst",
  "graphic-designer",
  "qa-engineer",
  "accountant",
  "content-writer",
];
const TIERS = ["easy", "medium", "hard"];
const normalise = (text: string) =>
  text.trim().toLowerCase().replace(/\s+/g, " ");

function count<T>(items: T[], pick: (item: T) => string): Map<string, number> {
  const out = new Map<string, number>();
  for (const item of items) {
    const key = pick(item);
    out.set(key, (out.get(key) ?? 0) + 1);
  }
  return out;
}

const ignore = file === null;

Deno.test({
  name: "the pool migration has its six blocks and turns seeding on first",
  ignore,
  fn() {
    assertEquals(Object.keys(blocks()).sort(), [
      "aliases",
      "packs",
      "paths",
      "pool",
      "roles",
      "sets",
    ]);
    const statements = sql.split("\n").filter((l) =>
      l.trim() !== "" && !l.startsWith("--")
    );
    assertEquals(statements[0], "set local tack.seeding = 'on';");
  },
});

Deno.test({
  name: "every role is named by its own slug and sits in a real field",
  ignore,
  async fn() {
    const roles = blocks().roles as Role[];
    const fields = new Set(
      (await Deno.readTextFile(
        new URL("../../../seed/career_fields.txt", import.meta.url),
      )).split("\n").filter((l) => l.trim()).map((l) => l.split("|")[0].trim()),
    );
    for (const role of roles) {
      assertEquals(slugifyRole(role.title), role.slug, role.title);
      assert(fields.has(role.field), `${role.slug}: ${role.field}`);
    }
    const slugs = new Set(roles.map((r) => r.slug));
    for (const required of ["management-trainee", ...LEGACY]) {
      assert(slugs.has(required), `${required} is missing`);
    }
    const defaults = count(
      roles.filter((r) => r.field_default),
      (r) => r.field,
    );
    for (const field of new Set(roles.map((r) => r.field))) {
      assertEquals(defaults.get(field), 1, `${field} defaults`);
    }
  },
});

Deno.test({
  name: "fifteen questions per role, five per tier; 24 behavioural, 8 per tier",
  ignore,
  fn() {
    const { roles, pool } = blocks() as {
      roles: Role[];
      pool: PoolQuestion[];
    };
    for (const role of roles) {
      const own = pool.filter((q) => q.role === role.slug);
      assertEquals(own.length, 15, role.slug);
      const tiers = count(own, (q) => q.difficulty);
      for (const tier of TIERS) assertEquals(tiers.get(tier), 5, role.slug);
      assert(own.every((q) => q.kind === "role"), role.slug);
    }
    const behavioural = pool.filter((q) => q.role === null);
    assertEquals(behavioural.length, 24);
    assert(behavioural.every((q) => q.kind === "behavioural"));
    const tiers = count(behavioural, (q) => q.difficulty);
    for (const tier of TIERS) assertEquals(tiers.get(tier), 8, tier);
    assert(
      behavioural.filter((q) => q.category === "HR round").length >= 4,
      "the HR round",
    );
  },
});

Deno.test({
  name: "every question has 2 to 4 key points, ids and texts unique",
  ignore,
  fn() {
    const pool = blocks().pool as PoolQuestion[];
    for (const q of pool) {
      assert(
        Array.isArray(q.key_points) && q.key_points.length >= 2 &&
          q.key_points.length <= 4,
        q.question,
      );
      for (const point of q.key_points) {
        assert(
          typeof point === "string" && point.length > 0 && point.length <= 120,
          `${q.question}: ${point}`,
        );
      }
    }
    assertEquals(new Set(pool.map((q) => q.id)).size, pool.length);
    const texts = pool.map((q) => `${q.role ?? ""}|${normalise(q.question)}`);
    assertEquals(new Set(texts).size, texts.length);
  },
});

Deno.test({
  name: "old app builds get 9 sets per role, each with five questions",
  ignore,
  fn() {
    const { roles, sets } = blocks() as { roles: Role[]; sets: FixedSet[] };
    const perRole = count(sets, (s) => s.role);
    for (const role of roles) assertEquals(perRole.get(role.slug), 9);
    for (const set of sets) {
      assert(set.questions.length >= 5, `${set.role} ${set.session_type}`);
      assert(
        set.questions.every((q) =>
          typeof q.question === "string" && q.question.length > 0
        ),
        `${set.role} ${set.session_type} ${set.difficulty}`,
      );
    }
  },
});

Deno.test({
  name: "company packs say only what kind of business each is",
  ignore,
  fn() {
    assertEquals(blocks().packs, [
      { slug: "bkash", about: "Mobile financial services." },
      { slug: "grameenphone", about: "Mobile network operator." },
      { slug: "pathao", about: "Ride-hailing, delivery and courier services." },
      { slug: "brac", about: "Development organisation." },
      { slug: "robi", about: "Mobile network operator." },
      { slug: "shohoz", about: "Online tickets, rides and logistics." },
    ]);
  },
});
